60	    .from("journal_entries")
61	    .select("journal_lines(debit, credit, account_id)")
62	    .eq("business_id", businessId)
63	    .gte("date", fromIso)
64	    .lt("date", toIsoExclusive);
65	
66	  const actualByAccount = new Map<string, number>();
67	  for (const e of entries ?? []) {
68	    const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
69	    for (const l of lines) {
70	      const cur = actualByAccount.get(l.account_id) ?? 0;
71	      actualByAccount.set(l.account_id, cur + Number(l.debit) - Number(l.credit));
