84	    const variance = actual - target;
85	    const pct = target > 0 ? Math.round((actual / target) * 100) : null;
86	    return { ...a, target, actual, variance, pct, hasBudget: !!budget };
87	  });
88	
89	  const pendapatanRows = rows.filter((r) => r.type === "pendapatan");
90	  const bebanRows = rows.filter((r) => r.type === "beban");
91	
92	  return (
93	    <div className="w-full max-w-2xl">
