109	          >
110	            Tampilkan
111	          </button>
112	        </form>
113	      </div>
114	
115	      <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
116	        <h2 className="mb-4 text-sm font-semibold text-zinc-900">Set Target Bulan Ini</h2>
117	        <AddBudgetForm action={boundSetBudget} period={period} accounts={accounts ?? []} />
118	      </div>
119	
120	      {[
