129	            {group.list.filter((r) => r.hasBudget).length > 0 ? (
130	              group.list
131	                .filter((r) => r.hasBudget)
132	                .map((r) => (
133	                  <div key={r.id} className="flex items-center justify-between gap-3 py-3">
134	                    <div className="min-w-0">
