63	    .eq("business_id", businessId);
64	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
65	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
66	  const { data: transactions } = await txQuery;
67	
68	  const validTx = (transactions ?? []).filter((t) => !t.voided);
69	
70	  const byProduct = new Map<string, Row>();
71	  const byCategory = new Map<string, Row>();
72	
73	  for (const t of validTx) {
74	    for (const i of t.transaction_items) {
75	      const qty = Number(i.qty);
