  });

  await logActivity(
    supabase,
    businessId,
    "sistem",
    "info",
    "Bayar utang dagang",
    `Rp${amount.toLocaleString("id-ID")}${note ? ` · ${note}` : ""}`,
  );

  revalidatePath(`/business/${businessId}/purchases`);
  revalidatePath(`/business/${businessId}/suppliers`);
  return { error: null };
}

