1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { createClient } from "@/lib/supabase/server";
4	import {
5	  PERIOD_DESCRIPTIONS,
6	  PERIOD_LABELS,
7	  getPeriodRange,
8	  parsePeriod,
9	  type Period,
10	} from "../../reports/period";
11	
12	const KAS_ACCOUNT_CODE = "1-001";
13	
14	const OPERASIONAL_SOURCES = new Set(["penjualan", "void", "pembelian", "beban", "payroll"]);
15	
16	const SOURCE_LABELS: Record<string, string> = {
17	  penjualan: "Penjualan",
18	  void: "Void transaksi",
19	  pembelian: "Pembelian",
20	  beban: "Beban operasional",
21	  payroll: "Payroll",
22	  manual: "Investasi & Pendanaan (manual)",
23	};
24	
25	function formatRupiah(value: number) {
26	  const sign = value < 0 ? "-" : "";
27	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
28	}
29	
30	export default async function ArusKasPage({
31	  params,
32	  searchParams,
33	}: {
34	  params: Promise<{ businessId: string }>;
35	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
36	}) {
37	  const { businessId } = await params;
38	  const { period: periodParam, from, to } = await searchParams;
39	  const period = parsePeriod(periodParam);
40	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
41	
42	  const supabase = await createClient();
43	
44	  const { data: business } = await supabase
45	    .from("businesses")
46	    .select("id, name")
47	    .eq("id", businessId)
48	    .single();
49	
50	  if (!business) {
51	    notFound();
52	  }
53	
54	  const { data: kasAccount } = await supabase
55	    .from("accounts")
56	    .select("id")
57	    .eq("business_id", businessId)
58	    .eq("code", KAS_ACCOUNT_CODE)
59	    .single();
60	
61	  const kasAccountId = kasAccount?.id;
62	
63	  // Saldo kas sebelum periode ini (untuk saldo awal).
64	  let openingBalance = 0;
65	  if (kasAccountId && fromIso) {
66	    const { data: priorEntries } = await supabase
67	      .from("journal_entries")
68	      .select("journal_lines(debit, credit, account_id)")
69	      .eq("business_id", businessId)
70	      .lt("date", fromIso);
71	    for (const e of priorEntries ?? []) {
72	      const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
73	      for (const l of lines) {
74	        if (l.account_id === kasAccountId) {
75	          openingBalance += Number(l.debit) - Number(l.credit);
76	        }
77	      }
78	    }
79	  }
80	
81	  // Arus kas di periode ini, dikelompokkan per sumber.
82	  let entryQuery = supabase
83	    .from("journal_entries")
84	    .select("source, journal_lines(debit, credit, account_id)")
85	    .eq("business_id", businessId);
86	  if (fromIso) entryQuery = entryQuery.gte("date", fromIso);
87	  if (toIsoExclusive) entryQuery = entryQuery.lt("date", toIsoExclusive);
88	  const { data: entries } = await entryQuery;
89	
90	  const bySource = new Map<string, { masuk: number; keluar: number }>();
91	  for (const e of entries ?? []) {
92	    const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
93	    for (const l of lines) {
94	      if (l.account_id !== kasAccountId) continue;
95	      const cur = bySource.get(e.source) ?? { masuk: 0, keluar: 0 };
96	      cur.masuk += Number(l.debit);
97	      cur.keluar += Number(l.credit);
98	      bySource.set(e.source, cur);
99	    }
100	  }
101	
102	  const rows = Array.from(bySource.entries())
103	    .map(([source, v]) => ({ source, ...v, net: v.masuk - v.keluar }))
104	    .sort((a, b) => Math.abs(b.net) - Math.abs(a.net));
105	
106	  const operasionalRows = rows.filter((r) => OPERASIONAL_SOURCES.has(r.source));
107	  const lainnyaRows = rows.filter((r) => !OPERASIONAL_SOURCES.has(r.source));
108	
109	  const totalMasuk = rows.reduce((s, r) => s + r.masuk, 0);
110	  const totalKeluar = rows.reduce((s, r) => s + r.keluar, 0);
111	  const netCashFlow = totalMasuk - totalKeluar;
112	  const closingBalance = openingBalance + netCashFlow;
113	
114	  return (
115	    <div className="w-full max-w-2xl">
116	      <div className="flex flex-wrap items-center justify-between gap-2">
117	        <div>
118	          <h1 className="text-lg font-bold text-zinc-900">Laporan Arus Kas — {business.name}</h1>
119	          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
120	        </div>
121	        <div className="flex flex-wrap gap-1.5">
122	          {(["today", "week", "month", "all", "custom"] as Period[]).map((p) => (
123	            <Link
124	              key={p}
125	              href={`/business/${businessId}/accounting/arus-kas?period=${p}`}
126	              className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
127	                p === period
128	                  ? "bg-brand-600 text-white"
129	                  : "bg-white text-zinc-600 hover:bg-zinc-100"
130	              }`}
131	            >
132	              {PERIOD_LABELS[p]}
133	            </Link>
134	          ))}
135	        </div>
136	      </div>
137	
138	      {period === "custom" && (
139	        <form
140	          method="get"
141	          className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
142	        >
143	          <input type="hidden" name="period" value="custom" />
144	          <label className="text-xs font-medium text-zinc-600">
145	            Dari
146	            <input
147	              type="date"
148	              name="from"
149	              defaultValue={from}
150	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
151	            />
152	          </label>
153	          <label className="text-xs font-medium text-zinc-600">
154	            Sampai
155	            <input
156	              type="date"
157	              name="to"
158	              defaultValue={to}
159	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
160	            />
161	          </label>
162	          <button
163	            type="submit"
164	            className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
165	          >
166	            Terapkan
167	          </button>
168	        </form>
169	      )}
170	
171	      <div className="mt-6 grid grid-cols-2 gap-3">
172	        <div className="rounded-2xl border border-zinc-200 bg-white p-4">
173	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Kas Masuk</p>
174	          <p className="text-xl font-bold text-zinc-900">{formatRupiah(totalMasuk)}</p>
175	        </div>
176	        <div className="rounded-2xl border border-zinc-200 bg-white p-4">
177	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Kas Keluar</p>
178	          <p className="text-xl font-bold text-zinc-900">{formatRupiah(totalKeluar)}</p>
179	        </div>
180	      </div>
181	
182	      <div className="mt-4 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
183	        <div className="border-b border-zinc-100 px-4 py-3">
184	          <h2 className="text-sm font-bold text-zinc-900">Aktivitas Operasional</h2>
185	        </div>
186	        <div className="divide-y divide-zinc-50 px-4">
187	          {operasionalRows.length > 0 ? (
188	            operasionalRows.map((r) => (
189	              <div key={r.source} className="flex items-center justify-between py-2 text-xs">
190	                <span className="text-zinc-600">{SOURCE_LABELS[r.source] ?? r.source}</span>
191	                <span className={`font-medium ${r.net >= 0 ? "text-zinc-800" : "text-red-500"}`}>
192	                  {r.net >= 0 ? "+" : ""}
193	                  {formatRupiah(r.net)}
194	                </span>
195	              </div>
196	            ))
197	          ) : (
198	            <p className="py-6 text-center text-xs text-zinc-300">Belum ada aktivitas</p>
199	          )}
200	        </div>
201	      </div>
202	
203	      {lainnyaRows.length > 0 && (
204	        <div className="mt-4 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
205	          <div className="border-b border-zinc-100 px-4 py-3">
206	            <h2 className="text-sm font-bold text-zinc-900">Investasi &amp; Pendanaan</h2>
207	          </div>
208	          <div className="divide-y divide-zinc-50 px-4">
209	            {lainnyaRows.map((r) => (
210	              <div key={r.source} className="flex items-center justify-between py-2 text-xs">
211	                <span className="text-zinc-600">{SOURCE_LABELS[r.source] ?? r.source}</span>
212	                <span className={`font-medium ${r.net >= 0 ? "text-zinc-800" : "text-red-500"}`}>
213	                  {r.net >= 0 ? "+" : ""}
214	                  {formatRupiah(r.net)}
215	                </span>
216	              </div>
217	            ))}
218	          </div>
219	        </div>
220	      )}
221	
222	      <div className="mt-4 overflow-hidden rounded-2xl border border-brand-200 bg-brand-50">
223	        <div className="divide-y divide-brand-100 px-4">
224	          <div className="flex items-center justify-between py-2.5 text-xs text-brand-700">
225	            <span>Saldo Kas Awal</span>
226	            <span className="font-semibold">{formatRupiah(openingBalance)}</span>
227	          </div>
228	          <div className="flex items-center justify-between py-2.5 text-xs text-brand-700">
229	            <span>Arus Kas Bersih Periode Ini</span>
230	            <span className="font-semibold">
231	              {netCashFlow >= 0 ? "+" : ""}
232	              {formatRupiah(netCashFlow)}
